    def prerelease_key(identifier: str):
        if identifier.isascii() and identifier.isdigit():
            digits = identifier.lstrip("0") or "0"
            return (0, len(digits), digits)
        if identifier.isdigit():
            # Preserve the constructor's treatment of Unicode digits,
            # including ValueError for digits int() cannot convert.
            digits = str(int(identifier))
            return (0, len(digits), digits)
        return (1, identifier)

    # Build both lists eagerly so invalid Unicode digits raise even if an
    # earlier identifier would determine the comparison.
    a_parts = [prerelease_key(x) for x in (a or "").split(".")]
    b_parts = [prerelease_key(x) for x in (b or "").split(".")]

    for sub_a, sub_b in zip(a_parts, b_parts):
        cmp_result = _cmp(sub_a, sub_b)
        if cmp_result != 0:
            return cmp_result

